@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&display=swap');
:root{color-scheme:dark;--bg:#101a16;--panel:#17231e;--panel2:#1d2b24;--line:rgba(207,225,199,.11);--muted:#91a096;--text:#e7eddf;--lime:#c0d47a;--mint:#8ebc88;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}
*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:var(--bg);color:var(--text);font-family:var(--sans);overflow:hidden;background-image:radial-gradient(ellipse at 38% 55%,#1a2a21 0,transparent 58%),linear-gradient(130deg,#101a16,#111b17 52%,#152019)}button{font:inherit;color:inherit;cursor:pointer}.game-shell{height:100dvh;min-height:620px;max-width:1800px;margin:auto;padding:0 36px;display:flex;flex-direction:column}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);flex:none}.brand{display:flex;align-items:center;gap:11px;color:var(--text);text-decoration:none;font-size:12px;letter-spacing:.18em;font-weight:700}.brand-mark{color:var(--lime);font-size:23px}.world-label{font:10px var(--mono);letter-spacing:.14em;color:#a6b0a7;display:flex;align-items:center;gap:12px}.live-dot{height:6px;width:6px;border-radius:50%;background:#a4ce8c;box-shadow:0 0 10px #a4ce8c}.separator{color:#4b5a50}.icon-button{width:29px;height:29px;border:1px solid #536257;border-radius:50%;background:none;color:#b9c5b6;font:12px var(--mono}.game-layout{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 370px;padding:24px 0;gap:0}.world-frame{position:relative;overflow:hidden;border:1px solid rgba(185,205,172,.15);border-right:0;background:#1a2821;box-shadow:inset 0 0 110px rgba(0,0,0,.24)}#world{width:100%;height:100%;display:block;touch-action:none;cursor:crosshair}.world-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(9,17,13,.4) 100%),linear-gradient(0deg,rgba(8,15,12,.5),transparent 25%,transparent 80%,rgba(8,15,12,.18)}.world-caption{pointer-events:none;position:absolute;left:28px;top:24px;display:flex;flex-direction:column;gap:7px;font:9px var(--mono);letter-spacing:.15em;color:rgba(219,232,207,.72)}.caption-kicker{font-size:8px;color:#8da286;letter-spacing:.2em}.world-controls{position:absolute;left:27px;bottom:22px;font:8px var(--mono);letter-spacing:.12em;color:#89968a;pointer-events:none}.control-dot{padding:0 8px;color:#bdca9b}.side-panel{padding:24px 28px;background:linear-gradient(155deg,rgba(27,40,33,.98),rgba(22,33,27,.98));border:1px solid var(--line);border-left:1px solid rgba(188,211,172,.17);overflow-y:auto;scrollbar-width:thin;scrollbar-color:#405044 transparent}.panel-head{display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{margin:0 0 8px;color:#92a194;font:8px var(--mono);letter-spacing:.17em}.panel-head h1{font:600 36px/.99 var(--serif);letter-spacing:-.03em;margin:0;color:#e5eadc}.panel-head h1 em,.modal-card h2 em{font-weight:600;color:var(--lime)}.chapter-mark{font:10px var(--mono);line-height:1.55;text-align:center;color:#839287;padding-top:5px}.chapter-mark i{font-style:normal;color:var(--lime)}.intro{margin:14px 0 18px;font-size:11px;line-height:1.65;color:#a1afa3;max-width:265px}.vitals{display:grid;grid-template-columns:1fr 1fr;gap:8px}.vital-card{padding:12px 12px 10px;background:rgba(225,239,213,.035);border:1px solid var(--line);min-height:75px}.vital-top{display:flex;align-items:center;justify-content:space-between}.vital-value{font:17px var(--mono);color:#e2ead8}.vital-top .eyebrow{margin:0;font-size:7px}.sap-icon{font-size:11px;color:var(--lime);margin-right:3px}.meter{height:3px;background:#334138;margin:7px 0 7px}.health-fill{display:block;width:100%;height:100%;background:#a5c878;transition:width .25s}.vital-foot{display:flex;justify-content:space-between;font:7px var(--mono);letter-spacing:.08em;color:#7f9082}.sap-card .vital-foot{margin-top:13px}.wave-card{margin-top:12px;padding:12px;background:#1a2921;border:1px solid rgba(192,212,122,.19);position:relative;overflow:hidden}.wave-top,.wave-bottom{display:flex;justify-content:space-between;align-items:center}.wave-top strong{font:10px var(--mono);letter-spacing:.05em;color:#d9e3ce}.wave-icon{font-size:22px;color:#c0d47a;opacity:.8}.wave-bottom{margin-top:9px}.wave-bottom>span{font-size:9px;color:#97a698}.wave-bottom b{color:#d7e1ca;font:10px var(--mono)}.summon-btn{border:1px solid #718358;background:#9fb570;color:#182018;font:8px var(--mono);letter-spacing:.06em;padding:8px 10px}.summon-btn span{padding-left:8px}.summon-btn:hover,.primary-button:hover{background:#c2d58f}.wave-progress{position:absolute;bottom:0;left:0;right:0;height:2px;background:#28382e}.wave-progress span{display:block;height:100%;width:0;background:#b9cf7a;transition:width .3s}.build-heading{display:flex;justify-content:space-between;align-items:flex-end;margin:19px 0 8px}.build-note{display:block;font-size:9px;color:#88978a}.build-count{text-align:right;font:16px var(--mono);line-height:.95;color:#c4d58c}.build-count small{font-size:7px;color:#839287;letter-spacing:.12em}.build-list{display:flex;flex-direction:column;gap:4px}.build-option{height:42px;width:100%;display:flex;align-items:center;text-align:left;background:rgba(234,244,227,.025);border:1px solid transparent;padding:0 9px;gap:10px;transition:background .15s,border-color .15s}.build-option:hover{background:rgba(230,243,216,.07)}.build-option.selected{background:rgba(190,210,137,.1);border-color:rgba(190,210,137,.4)}.tile-symbol{width:25px;height:25px;display:grid;place-items:center;font-size:19px;background:#28382e;color:#b4cf8d}.leaf-symbol{color:#9acb8b}.root-symbol{color:#c79b75}.bloom-symbol{color:#e4ba78}.glyph-symbol{color:#b3a5db}.tile-info{display:flex;flex:1;flex-direction:column;gap:2px}.tile-info strong{font-size:10px;font-weight:600}.tile-info small{font-size:8px;color:#859387}.tile-cost{font:9px var(--mono);color:#c9d69f;white-space:nowrap}.tile-key{font:8px var(--mono);color:#829084;border:1px solid #455349;padding:2px 4px;margin-left:4px}.module-strip{display:flex;align-items:center;gap:10px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:10px 0;margin-top:12px}.module-icon{height:26px;width:26px;display:grid;place-items:center;color:#c3d58c;background:#29392e;font-size:16px}.module-strip b{display:block;font-size:9px;font-weight:600;color:#d5dfce}.module-strip small{display:block;margin-top:3px;font-size:8px;color:#869488}.pause-button{margin-top:11px;width:100%;height:30px;background:none;border:1px solid var(--line);text-align:left;padding:0 10px;color:#9da99d;font:8px var(--mono);letter-spacing:.1em}.pause-button>span{font-size:12px;margin-right:8px;color:#c5d493}.pause-button kbd{float:right;border:1px solid #4b584e;padding:3px 4px;color:#819083;font:8px var(--mono)}.footer{height:37px;display:flex;justify-content:space-between;align-items:center;font:8px var(--mono);letter-spacing:.1em;color:#77857a;flex:none}.footer i{font-style:normal;color:#bccb8a;padding:0 5px}.footer b{font-size:13px;font-weight:400;color:#bed184;margin-left:8px}.toast{position:absolute;z-index:3;left:50%;top:20%;transform:translate(-50%,-6px);opacity:0;pointer-events:none;padding:9px 13px;background:rgba(17,27,21,.92);border:1px solid rgba(205,225,182,.3);color:#dce7d3;font:9px var(--mono);letter-spacing:.04em;transition:opacity .2s,transform .2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:10;background:rgba(6,12,9,.76);display:grid;place-items:center;padding:20px;backdrop-filter:blur(8px)}.modal-backdrop.hidden{display:none}.modal-card{position:relative;width:min(460px,100%);padding:35px 38px 31px;background:#19261f;border:1px solid rgba(196,216,171,.22);box-shadow:0 20px 90px #070d09}.modal-close{position:absolute;right:18px;top:15px;border:0;background:none;color:#9ba99b;font-size:24px}.modal-card h2{margin:0 0 18px;font:600 34px/1.05 var(--serif);letter-spacing:-.03em}.modal-copy p{font-size:12px;line-height:1.7;color:#aab7aa;margin:12px 0}.modal-copy b{color:#e2e8d9}.primary-button{margin-top:13px;padding:12px 14px;border:0;background:#a6bb7c;color:#182019;font:9px var(--mono);letter-spacing:.08em}.primary-button span{margin-left:13px}.modal-result{text-align:center}.modal-result h2{font-size:39px}.modal-result .modal-copy{color:#aab7aa}
@media(max-width:1050px){.game-shell{padding:0 20px}.game-layout{grid-template-columns:minmax(0,1fr) 330px}.side-panel{padding:20px}.panel-head h1{font-size:32px}}
@media(max-width:760px){html,body{overflow:auto;min-height:100%}.game-shell{height:auto;min-height:100dvh;padding:0 12px}.topbar{height:54px}.brand{font-size:10px}.brand-mark{font-size:19px}.world-label{font-size:8px;gap:7px}.game-layout{display:flex;flex-direction:column;padding:10px 0 8px;gap:0}.world-frame{height:min(48dvh,410px);min-height:275px;border-right:1px solid rgba(185,205,172,.15)}.world-caption{left:14px;top:14px;font-size:8px}.world-controls{left:14px;bottom:13px;font-size:7px}.side-panel{padding:17px 15px;border-top:0;overflow:visible}.panel-head h1{font-size:29px}.intro{margin:9px 0 12px}.vitals{gap:6px}.vital-card{padding:9px;min-height:65px}.wave-card{margin-top:8px}.build-heading{margin-top:13px}.build-list{display:grid;grid-template-columns:1fr 1fr;gap:5px}.build-option{height:43px;padding:0 6px;gap:6px}.build-option:last-child{grid-column:span 2}.tile-symbol{width:24px;height:25px;flex:none}.tile-info small{font-size:7px}.tile-cost{font-size:8px}.tile-key{display:none}.module-strip{margin-top:10px}.pause-button{margin-top:8px}.footer{height:30px;font-size:6px}.footer span:last-child{display:none}.modal-card{padding:30px 24px 25px}.modal-card h2{font-size:30px}}
@media(max-width:380px){.world-label{letter-spacing:.02em}.game-shell{padding:0 8px}.side-panel{padding:14px 11px}.build-option{gap:5px}.tile-info strong{font-size:9px}.tile-info small{font-size:6px}.tile-cost{font-size:7px}}

