node <<'JS'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1440,height:900}});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8765/',{waitUntil:'networkidle'});
 await page.screenshot({path:'/tmp/opencode/rootbound-desktop.png'});
 const initial=await page.evaluate(()=>({rules:document.styleSheets[0].cssRules.length,canvas:[document.querySelector('canvas').width,document.querySelector('canvas').height],world:document.querySelector('.world-frame').getBoundingClientRect().toJSON(),health:document.querySelector('#healthText').textContent,sap:document.querySelector('#sapText').textContent}));
 await page.locator('[data-type="leaf"]').click();
 const box=await page.locator('#world').boundingBox();
 await page.mouse.click(box.x+box.width/2+24,box.y+box.height/2+20+12.5);
 const afterPlace=await page.evaluate(()=>({tiles:document.querySelector('#tileCount').innerText,sap:document.querySelector('#sapText').textContent,income:document.querySelector('#incomeText').textContent,module:document.querySelector('#moduleTitle').textContent}));
 await page.locator('#waveBtn').click();
 await page.waitForTimeout(1400);
 const wave=await page.locator('#waveTitle').textContent();
 await page.locator('#pauseBtn').click();
 const paused=await page.locator('#pauseBtn').textContent();
 await page.locator('#helpBtn').click();
 const helpVisible=await page.locator('#modal').isVisible();
 await page.locator('#modalClose').click();
 await page.setViewportSize({width:390,height:844});
 await page.screenshot({path:'/tmp/opencode/rootbound-mobile.png',fullPage:true});
 const mobile=await page.evaluate(()=>({viewport:[innerWidth,innerHeight],document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],world:document.querySelector('.world-frame').getBoundingClientRect().toJSON(),panel:document.querySelector('.side-panel').getBoundingClientRect().toJSON()}));
 console.log(JSON.stringify({initial,afterPlace,wave,paused,helpVisible,mobile,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
