 await page.screenshot({path:'/tmp/opencode/rootbound-mobile.png',fullPage:true});
 const mobile=await page.evaluate(()=>({viewport:[innerWidth,innerHeight],document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],world:{x:document.querySelector('.world-frame').getBoundingClientRect().x,y:document.querySelector('.world-frame').getBoundingClientRect().y,width:document.querySelector('.world-frame').getBoundingClientRect().width,height:document.querySelector('.world-frame').getBoundingClientRect().height},panel:{x:document.querySelector('.side-panel').getBoundingClientRect().x,y:document.querySelector('.side-panel').getBoundingClientRect().y,width:document.querySelector('.side-panel').getBoundingClientRect().width,height:document.querySelector('.side-panel').getBoundingClientRect().height}}));
 console.log(JSON.stringify({initial,afterPlace,wave,paused,helpVisible,mobile,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
